/**
 * Legacy Studios office pack — Tier 12.
 *
 * Three tools around one small business file, data/studio.json:
 *   studio_rates      — read the service rate card (and business details)
 *   create_quotation  — itemized quotation as a clean printable document
 *   create_invoice    — itemized invoice, same treatment
 *
 * The studio file is seeded ONCE with Shahyd's real rate card and lives in
 * data/ so it survives upgrades and can be edited by hand — prices, studio
 * contact details, payment info, all in Notepad. Document numbering
 * (LS-QTN-0001, LS-INV-0001, …) is persistent in the same file.
 *
 * Documents are HTML files in data/documents/, opened via the /doc route and
 * printed to PDF from the browser. Creating a document is safe (nothing is
 * sent anywhere) — SENDING one to a client is a different act and will pass
 * the confirmation gate when sending tools exist.
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { registerTool } from './registry.js';
import { config } from '../config.js';
import { pushCard } from '../cards.js';
import { upsertClient } from './clients.js';

const DATA_DIR = fileURLToPath(new URL('../../data/', import.meta.url));
const STUDIO_FILE = join(DATA_DIR, 'studio.json');
const DOCS_DIR = join(DATA_DIR, 'documents');

/** Shahyd's real rate card — seeds the file on first run, then HIS edits rule. */
const SEED = {
  business: {
    name: 'Legacy Studios',
    tagline: 'Recording · Mixing · Mastering · Scoring',
    contact: 'EDIT ME in data/studio.json — phone / email',
    address: 'EDIT ME in data/studio.json — address, Malé, Maldives',
    payment: 'EDIT ME in data/studio.json — e.g. Bank transfer: BML account 7700-XXXXXX',
  },
  currency: 'MVR',
  usdRate: 15.42, // MVR per 1 USD — edit in data/studio.json when it drifts
  rates: [
    { id: 'original_song', name: 'Original song — recording, mixing & mastering', price: 8000 },
    { id: 'cover_song', name: 'Cover song — recording, mixing & mastering', price: 5000 },
    { id: 'mix_master', name: 'Mixing & mastering', price: 3000 },
    { id: 'jingle', name: 'Jingle composing', price: 1500 },
    { id: 'movie_score', name: 'Movie score', price: 30000 },
    { id: 'foley', name: 'Foley work', price: 10000 },
    { id: 'dubbing_tv', name: 'Dubbing — TV episode', price: 500, note: 'per episode' },
    { id: 'dubbing_movie', name: 'Dubbing — movie', price: 10000, note: 'per movie' },
    { id: 'ad_music', name: 'Ad music', priceMin: 1500, priceMax: 3000, note: 'depending on scope' },
  ],
  nextQuotation: 1,
  nextInvoice: 1,
};

function loadStudio() {
  try {
    return JSON.parse(readFileSync(STUDIO_FILE, 'utf8'));
  } catch {
    mkdirSync(DATA_DIR, { recursive: true });
    writeFileSync(STUDIO_FILE, JSON.stringify(SEED, null, 2) + '\n');
    return JSON.parse(JSON.stringify(SEED));
  }
}
function saveStudio(s) {
  writeFileSync(STUDIO_FILE, JSON.stringify(s, null, 2) + '\n');
}

// Currency-aware money formatter. Amounts are stored in MVR (the base);
// USD documents convert at studio.usdRate and print with a note.
const money = (n, currency = 'MVR', usdRate = 15.42) => {
  if (currency === 'USD') return `USD ${(Number(n) / usdRate).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  return `MVR ${Number(n).toLocaleString('en-US')}`;
};
// Back-compat: the rate card and ledger always speak MVR.
const mvr = (n) => money(n, 'MVR');

function rateLine(r) {
  const price = r.price != null ? mvr(r.price) : `${mvr(r.priceMin)} – ${mvr(r.priceMax)}`;
  return `• ${r.name}: ${price}${r.note ? ` (${r.note})` : ''}`;
}

registerTool({
  name: 'studio_rates',
  description:
    "Read Legacy Studios' service rate card and business details. Use whenever " +
    'Shahyd asks about prices, what to charge, or before building a quotation ' +
    'or invoice — quote HIS real prices, never invented ones. Ranged services ' +
    '(like ad music) need Shahyd to pick the exact price for a document.',
  inputSchema: { type: 'object', properties: {} },
  handler: () => {
    const s = loadStudio();
    return [
      `${s.business.name} — service rates (${s.currency}):`,
      ...s.rates.map(rateLine),
      ``,
      `Business details on documents: contact "${s.business.contact}", payment "${s.business.payment}".`,
      `Shahyd can edit rates and details anytime in data/studio.json.`,
    ].join('\n');
  },
});

/* ------------------------------------------------------------------ */
/* Document generation                                                  */
/* ------------------------------------------------------------------ */

function buildDocumentHTML({ kind, number, business, currency, usdRate, client, items, subtotal, discount, total, footerLine, notes }) {
  const m = (n) => money(n, currency, usdRate);
  const rows = items
    .map(
      (i) => `<tr>
        <td>${i.name}${i.note ? `<div class="inote">${i.note}</div>` : ''}</td>
        <td class="n">${i.qty}</td>
        <td class="n">${m(i.price)}</td>
        <td class="n">${m(i.qty * i.price)}</td>
      </tr>`
    )
    .join('\n');

  return `<!doctype html>
<html><head><meta charset="utf-8"><title>${number} — ${business.name}</title>
<style>
  body { font-family: Georgia, 'Times New Roman', serif; color: #221d17; margin: 0; padding: 48px 54px; max-width: 800px; }
  header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #b57b2e; padding-bottom: 18px; }
  .brand { font-size: 26px; font-weight: bold; letter-spacing: 0.14em; text-transform: uppercase; }
  .brandlogo { height: 34px; display: block; }
  .brand small { display: block; font-size: 11px; letter-spacing: 0.2em; color: #8a7f6e; margin-top: 4px; }
  .doctype { text-align: right; }
  .doctype h1 { margin: 0; font-size: 20px; letter-spacing: 0.2em; color: #b57b2e; }
  .doctype div { font-size: 12px; color: #555; margin-top: 4px; }
  .meta { display: flex; justify-content: space-between; margin: 26px 0 6px; font-size: 13px; }
  .meta .label { font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: #8a7f6e; }
  table { width: 100%; border-collapse: collapse; margin-top: 18px; font-size: 13px; }
  th { text-align: left; font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase; color: #8a7f6e; border-bottom: 1px solid #ccc; padding: 8px 6px; }
  td { border-bottom: 1px solid #eee; padding: 10px 6px; vertical-align: top; }
  td.n, th.n { text-align: right; white-space: nowrap; }
  .inote { font-size: 11px; color: #777; margin-top: 2px; }
  .totals { margin-top: 12px; margin-left: auto; width: 260px; font-size: 13px; }
  .totals div { display: flex; justify-content: space-between; padding: 4px 6px; }
  .totals .grand { border-top: 2px solid #b57b2e; font-weight: bold; font-size: 15px; margin-top: 4px; padding-top: 8px; }
  .foot { margin-top: 34px; font-size: 12px; color: #555; line-height: 1.7; }
  .foot .label { font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: #8a7f6e; display: block; }
  @media print { body { padding: 24px 30px; } }
</style></head><body>
<header>
  <div class="brand"><img class="brandlogo" src="data:image/png;base64," alt="${business.name}"><small>${business.tagline ?? ''}</small></div>
  <div class="doctype"><h1>${kind}</h1><div>${number}</div><div>${new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</div></div>
</header>
<div class="meta">
  <div><span class="label">${kind === 'INVOICE' ? 'Billed to' : 'Prepared for'}</span><br>${client}</div>
  <div style="text-align:right"><span class="label">From</span><br>${business.name}<br>${business.address}<br>${business.contact}</div>
</div>
<table>
  <thead><tr><th>Service</th><th class="n">Qty</th><th class="n">Rate</th><th class="n">Amount</th></tr></thead>
  <tbody>${rows}</tbody>
</table>
<div class="totals">
  <div><span>Subtotal</span><span>${m(subtotal)}</span></div>
  ${discount > 0 ? `<div><span>Discount</span><span>− ${m(discount)}</span></div>` : ''}
  <div class="grand"><span>Total (${currency})</span><span>${m(total)}</span></div>
</div>
<div class="foot">
  ${currency === 'USD' ? `<span class="label">Currency</span>Amounts in USD, converted from MVR at ${usdRate} MVR/USD.<br><br>` : ''}
  <span class="label">Payment</span>${business.payment}<br><br>
  ${footerLine}
  ${notes ? `<br><br><span class="label">Notes</span>${notes}` : ''}
</div>
</body></html>`;
}

function validateItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new Error('The document needs at least one line item: [{ name, price, qty?, note? }].');
  }
  return items.map((i) => {
    const price = Number(i.price);
    const qty = Number(i.qty ?? 1);
    if (!i.name?.trim()) throw new Error('Every item needs a service name.');
    if (!Number.isFinite(price) || price <= 0) {
      throw new Error(
        `Item "${i.name}" needs a definite price. For ranged services (like ad music), ask Shahyd which exact price to use.`
      );
    }
    if (!Number.isFinite(qty) || qty < 1) throw new Error(`Item "${i.name}" has an invalid quantity.`);
    return { name: i.name.trim(), price, qty, note: i.note?.trim() || null };
  });
}

function createDocument(kind, input, footerFor) {
  const { client, items, discountPercent = 0, notes } = input;
  const currency = (input.currency ?? 'MVR').toUpperCase();
  if (!['MVR', 'USD'].includes(currency)) throw new Error('Currency must be MVR or USD.');
  if (!client?.trim()) throw new Error(`The ${kind.toLowerCase()} needs a client name.`);
  const clean = validateItems(items);
  const s = loadStudio();

  const counterKey = kind === 'INVOICE' ? 'nextInvoice' : 'nextQuotation';
  const prefix = kind === 'INVOICE' ? 'LS-INV' : 'LS-QTN';
  const number = `${prefix}-${String(s[counterKey]).padStart(4, '0')}`;
  s[counterKey] += 1;
  saveStudio(s);

  const dueDate = kind === 'INVOICE'
    ? new Date(Date.now() + (input.dueDays ?? 14) * 86_400_000).toISOString().slice(0, 10)
    : null;
  const subtotal = clean.reduce((sum, i) => sum + i.price * i.qty, 0);
  const discount = Math.round(subtotal * (Math.min(Math.max(discountPercent, 0), 100) / 100));
  const total = subtotal - discount;

  const usdRate = s.usdRate ?? 15.42;
  const html = buildDocumentHTML({
    kind, number, business: s.business, currency, usdRate,
    client: client.trim(), items: clean, subtotal, discount, total,
    footerLine: footerFor(s), notes: notes?.trim(),
  });

  mkdirSync(DOCS_DIR, { recursive: true });
  const filename = `${number}-${client.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 30)}.html`;
  writeFileSync(join(DOCS_DIR, filename), html);

  upsertClient(client); // every client on paper joins the client list

  // The ledger: every invoice is tracked until Shahyd marks it paid.
  if (kind === 'INVOICE') {
    const s2 = loadStudio();
    s2.invoices = s2.invoices ?? [];
    s2.invoices.push({ number, client: client.trim(), total, dueDate, createdAt: new Date().toISOString(), paid: false, paidAt: null });
    saveStudio(s2);
  }

  const port = config.voice?.serverPort ?? 3000;
  pushCard({
    kind: 'document',
    title: `${kind === 'INVOICE' ? 'Invoice' : 'Quotation'} ${number}`,
    subtitle: `${client.trim()} — total ${money(total, currency, usdRate)}`,
    url: `/doc?f=${encodeURIComponent(filename)}`,
  });

  return {
    number, total,
    summary:
      `${kind === 'INVOICE' ? 'Invoice' : 'Quotation'} ${number} for ${client.trim()} — total ${money(total, currency, usdRate)}` +
      (discount ? ` (after ${discountPercent}% discount)` : '') +
      `.\nOpen and print to PDF: http://localhost:${port}/doc?f=${encodeURIComponent(filename)}`,
  };
}

registerTool({
  name: 'create_quotation',
  description:
    'Create a Legacy Studios QUOTATION as a clean printable document. Check ' +
    'studio_rates first and use the real prices; every item needs a definite ' +
    'price (ask Shahyd to pick one for ranged services). If Shahyd has not ' +
    'said which currency, ASK — MVR or USD — before creating it. Numbering is automatic.',
  inputSchema: {
    type: 'object',
    properties: {
      client: { type: 'string', description: 'Client or company name.' },
      currency: { type: 'string', enum: ['MVR', 'USD'], description: 'MVR (default) or USD. Ask Shahyd if unsure.' },
      items: {
        type: 'array',
        description: 'Line items.',
        items: {
          type: 'object',
          properties: {
            name: { type: 'string', description: 'Service name as it should appear.' },
            price: { type: 'number', description: 'Unit price in MVR.' },
            qty: { type: 'integer', description: 'Quantity, default 1.' },
            note: { type: 'string', description: 'Optional line note, e.g. "per episode".' },
          },
          required: ['name', 'price'],
        },
      },
      discountPercent: { type: 'number', description: 'Optional discount %, e.g. 10.' },
      validityDays: { type: 'integer', description: 'How long the quote stands. Default 14.' },
      notes: { type: 'string', description: 'Optional notes shown on the document.' },
    },
    required: ['client', 'items'],
  },
  handler: (input) => {
    const days = input.validityDays ?? 14;
    const { summary } = createDocument('QUOTATION', input, () =>
      `This quotation is valid for ${days} days from the date above. Prices in MVR and exclusive of any applicable taxes.`
    );
    return summary;
  },
});

registerTool({
  name: 'create_invoice',
  description:
    'Create a Legacy Studios INVOICE as a clean printable document. Check ' +
    'studio_rates first and use the real prices; every item needs a definite ' +
    'price. If Shahyd has not said which currency, ASK — MVR or USD — before ' +
    'creating it. Numbering is automatic (LS-INV-0001, …).',
  inputSchema: {
    type: 'object',
    properties: {
      client: { type: 'string', description: 'Client or company name.' },
      currency: { type: 'string', enum: ['MVR', 'USD'], description: 'MVR (default) or USD. Ask Shahyd if unsure.' },
      items: {
        type: 'array',
        description: 'Line items.',
        items: {
          type: 'object',
          properties: {
            name: { type: 'string' },
            price: { type: 'number', description: 'Unit price in MVR.' },
            qty: { type: 'integer', description: 'Quantity, default 1.' },
            note: { type: 'string' },
          },
          required: ['name', 'price'],
        },
      },
      discountPercent: { type: 'number' },
      dueDays: { type: 'integer', description: 'Payment due window. Default 14.' },
      notes: { type: 'string' },
    },
    required: ['client', 'items'],
  },
  handler: (input) => {
    const days = input.dueDays ?? 14;
    const due = new Date(Date.now() + days * 86_400_000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
    const { summary } = createDocument('INVOICE', input, () =>
      `Payment due by ${due} (${days} days). Please reference the invoice number with your payment.`
    );
    return summary;
  },
});

/** Unpaid invoices, soonest due first — the Pending Payments panel + reminders. */
export function pendingPayments() {
  const s = loadStudio();
  return (s.invoices ?? [])
    .filter((i) => !i.paid)
    .sort((a, b) => String(a.dueDate).localeCompare(String(b.dueDate)));
}

registerTool({
  name: 'mark_invoice_paid',
  description:
    'Mark an invoice as PAID by its number (e.g. "LS-INV-0002") when Shahyd ' +
    'says a client has paid. Clears it from Pending Payments. Check ' +
    'list_pending_payments if unsure of the number.',
  inputSchema: {
    type: 'object',
    properties: { number: { type: 'string', description: 'The invoice number, e.g. LS-INV-0002.' } },
    required: ['number'],
  },
  handler: ({ number }) => {
    const s = loadStudio();
    const inv = (s.invoices ?? []).find((i) => i.number === number.trim().toUpperCase());
    if (!inv) throw new Error(`No invoice ${number} in the ledger. Use list_pending_payments to see them.`);
    if (inv.paid) return `Invoice ${inv.number} was already marked paid.`;
    inv.paid = true; inv.paidAt = new Date().toISOString();
    saveStudio(s);
    return `Marked ${inv.number} (${inv.client}, ${mvr(inv.total)}) as PAID.`;
  },
});

registerTool({
  name: 'list_pending_payments',
  description:
    'List unpaid invoices with amounts and due dates. Use when Shahyd asks ' +
    'about pending payments, who owes him, or outstanding invoices — and use ' +
    'show_card to put the total owed on screen.',
  inputSchema: { type: 'object', properties: {} },
  handler: () => {
    const pending = pendingPayments();
    if (!pending.length) return 'No pending payments — every invoice is paid.';
    const total = pending.reduce((s2, i) => s2 + i.total, 0);
    return pending.map((i) => `• ${i.number} — ${i.client}: ${mvr(i.total)} (due ${i.dueDate})`).join('\n') +
      `\nTotal outstanding: ${mvr(total)}`;
  },
});
